-- Cuisinix : traductions (anglais, arabe, derja tunisienne)

alter table public.recipes add column if not exists translations jsonb;
alter table public.ingredients add column if not exists translations jsonb;

update public.recipes r set translations = v.t::jsonb
from (values
  ('Lablabi', '{"en": {"name": "Lablabi (chickpea soup)", "steps": "Soak the chickpeas overnight, then boil them until tender.\nCrush the garlic with salt, lemon juice and harissa.\nPut pieces of bread in bowls and pour the hot chickpeas with their broth over them.\nAdd the garlic mixture and a drizzle of olive oil, and an egg if you like."}, "ar": {"name": "لبلابي (حساء الحمص)", "steps": "انقع الحمص من الليلة السابقة ثم اسلقه حتى ينضج.\nاسحق الثوم مع الملح وعصير الليمون والهريسة.\nضع قطع الخبز في الأطباق وصبّ فوقها الحمص الساخن مع مرقه.\nأضف خليط الثوم وقليلا من زيت الزيتون، وبيضة إن أردت."}, "aeb": {"name": "لبلابي", "steps": "نقّع الحمص من البارح وبعد اسلقو حتى يطيب.\nدق الثوم بالملح وعصير الليمون والهريسة.\nحط الخبز مقطّع في الصحون وصبّ عليه الحمص سخون بالمرق متاعو.\nزيد الثوم وشوية زيت زيتون، وبيضة كان تحب."}}'),
  ('Omelette tunisienne', '{"en": {"name": "Tunisian omelette", "steps": "Fry the sliced onion and diced potato.\nBeat the eggs with chopped parsley, salt and pepper.\nPour over the vegetables and cook over medium heat on both sides."}, "ar": {"name": "عجة تونسية", "steps": "قلّ البصل المقطع والبطاطا المقطعة مكعبات.\nاخفق البيض مع البقدونس المفروم والملح والفلفل.\nاسكبه فوق الخضار واطهه على نار متوسطة من الجانبين."}, "aeb": {"name": "عجّة تونسية", "steps": "قلّي البصل والبطاطا مقطّعين.\nاخلط البيض بالمعدنوس مفروم والملح والفلفل.\nصبّو على الخضرة وطيّبو على نار متوسطة من الجهتين."}}'),
  ('Couscous au poulet', '{"en": {"name": "Chicken couscous", "steps": "Fry the onion and chicken, add the tomato, salt and spices, then cover with water.\nAdd the chickpeas and carrots, cook 30 minutes, then add the zucchini for 15 minutes.\nMoisten the semolina and steam it over the sauce, separating the grains by hand.\nServe the semolina with the sauce, chicken and vegetables."}, "ar": {"name": "كسكسي بالدجاج", "steps": "قلّ البصل والدجاج، ثم أضف الطماطم والملح والتوابل وغطّها بالماء.\nأضف الحمص والجزر واطهه 30 دقيقة، ثم أضف الكوسا لمدة 15 دقيقة.\nرطّب السميد واطهه على البخار فوق المرق مع تفتيت الحبوب بيدك.\nقدّم السميد مع المرق والدجاج والخضار."}, "aeb": {"name": "كسكسي بالدجاج", "steps": "قلّي البصل والدجاج، زيد الطماطم والملح والبهارات وغطيهم بالماء.\nزيد الحمص والجزر وطيّب 30 دقيقة، وبعد زيد القرعة 15 دقيقة.\nرطّب السميد واطيّبو بالبخار على المرق وفتّتو بيدك.\nقدّم الكسكسي بالمرق والدجاج والخضرة."}}'),
  ('Chakchouka', '{"en": {"name": "Shakshuka", "steps": "Fry the onion, garlic and sliced pepper in oil.\nAdd the tomato, harissa and salt, and cook 15 minutes.\nCrack the eggs over the sauce, cover and cook until the whites are set."}, "ar": {"name": "شكشوكة", "steps": "قلّ البصل والثوم والفلفل المقطع شرائح في الزيت.\nأضف الطماطم والهريسة والملح واطهه 15 دقيقة.\nاكسر البيض فوق الصلصة وغطّها واطهه حتى يتماسك بياضه."}, "aeb": {"name": "شكشوكة", "steps": "قلّي البصل والثوم والفلفل مقطّع في الزيت.\nزيد الطماطم والهريسة والملح وطيّب 15 دقيقة.\nكسّر البيض على الصلصة وغطّي وطيّب حتى يتجمّد البياض."}}'),
  ('Ojja merguez', '{"en": {"name": "Ojja with merguez", "steps": "Fry the garlic and pepper in oil, then add the tomato and harissa.\nAdd the sliced merguez and cook for 10 minutes.\nCrack the eggs over the sauce and cook covered for 3 to 5 minutes."}, "ar": {"name": "عجة بالمرقاز", "steps": "قلّ الثوم والفلفل في الزيت ثم أضف الطماطم والهريسة.\nأضف المرقاز المقطع واطهه 10 دقائق.\nاكسر البيض فوق الصلصة واطهه مغطى من 3 إلى 5 دقائق."}, "aeb": {"name": "عجّة بالمرڨاز", "steps": "قلّي الثوم والفلفل في الزيت وزيد الطماطم والهريسة.\nزيد المرڨاز مقطّع وطيّب 10 دقايق.\nكسّر البيض على الصلصة وغطّي وطيّب من 3 لـ5 دقايق."}}'),
  ('Salade méchouia', '{"en": {"name": "Mechouia salad", "steps": "Grill the peppers, tomatoes and chili peppers until the skin blackens.\nPeel them, remove the seeds and chop finely.\nMix with crushed garlic, lemon juice, olive oil and salt."}, "ar": {"name": "سلطة مشوية", "steps": "اشوِ الفلفل والطماطم والفلفل الحار حتى يسودّ جلدها.\nقشّرها وأزل البذور واقطعها ناعما.\nاخلطها مع الثوم المهروس وعصير الليمون وزيت الزيتون والملح."}, "aeb": {"name": "سلطة مشوية", "steps": "اشوي الفلفل والطماطم والفلفل الحار حتى يسوّد القشر.\nقشّرهم وشيل البزر وقطّعهم صغار.\nاخلطهم بالثوم مدقوق وعصير الليمون وزيت الزيتون والملح."}}'),
  ('Pâtes à la tomate', '{"en": {"name": "Pasta with tomato sauce", "steps": "Cook the pasta in salted water.\nFry the garlic in olive oil, add the tomato and cook for 10 minutes.\nMix the drained pasta with the sauce."}, "ar": {"name": "معكرونة بالطماطم", "steps": "اسلق المعكرونة في ماء مملح.\nقلّ الثوم في زيت الزيتون، ثم أضف الطماطم واطهه 10 دقائق.\nاخلط المعكرونة المصفاة مع الصلصة."}, "aeb": {"name": "مقرونة بالطماطم", "steps": "اسلق المقرونة في ماء بالملح.\nقلّي الثوم في زيت الزيتون، زيد الطماطم وطيّب 10 دقايق.\nاخلط المقرونة بعد ما تصفّيها بالصلصة."}}'),
  ('Soupe de lentilles', '{"en": {"name": "Lentil soup", "steps": "Fry the diced onion, garlic and carrot.\nAdd the rinsed lentils and cover with water, cook 25 minutes.\nBlend if you like a smooth soup, season and serve with lemon."}, "ar": {"name": "شوربة العدس", "steps": "قلّ البصل والثوم والجزر المقطع مكعبات صغيرة.\nأضف العدس المغسول وغطّه بالماء، واطهه 25 دقيقة.\nاهرسه بالخلاط إن أردت شوربة ناعمة، وتبّل وقدّمه مع الليمون."}, "aeb": {"name": "شربة عدس", "steps": "قلّي البصل والثوم والجزر مقطّعين صغار.\nزيد العدس مغسول وغطّي بالماء وطيّب 25 دقيقة.\nاطحنها بالخلاط كان تحب شربة ناعمة، زيد الملح وقدّمها بالليمون."}}'),
  ('Pain grillé à l''huile d''olive et harissa', '{"en": {"name": "Toast with olive oil and harissa", "steps": "Toast the bread slices.\nDrizzle with olive oil and spread with harissa.\nServe right away."}, "ar": {"name": "خبز محمص بزيت الزيتون والهريسة", "steps": "حمّص شرائح الخبز.\nرشّ عليها زيت الزيتون وادهنها بالهريسة.\nقدّمها مباشرة."}, "aeb": {"name": "خبز محمّص بزيت الزيتون والهريسة", "steps": "حمّص شرايح الخبز.\nصبّ عليها زيت زيتون وحط الهريسة.\nقدّمها في الحين."}}'),
  ('Msemen au miel', '{"en": {"name": "Msemen with honey", "steps": "Knead the flour with lukewarm water and salt, then rest 15 minutes.\nShape into balls, roll out very thin and brush with butter.\nFold each dough into a square and cook in a hot pan on both sides.\nServe warm with honey."}, "ar": {"name": "مسمن بالعسل", "steps": "اعجن الدقيق مع ماء فاتر وملح، ثم اتركه يرتاح 15 دقيقة.\nشكّل كرات وافردها رقيقة جدا ثم ادهنها بالزبدة.\nاطوِ كل عجينة على شكل مربع واطهها في مقلاة ساخنة من الجانبين.\nقدّمه دافئا مع العسل."}, "aeb": {"name": "مسمّن بالعسل", "steps": "اعجن الفرينة بماء دافي وملح وخليها ترتاح 15 دقيقة.\nاعمل كور وافردهم رقاق برشا وادهنهم بالزبدة.\nاطوي كل عجينة مربّع وطيّبها في مقلة سخونة من الجهتين.\nقدّمو دافي بالعسل."}}'),
  ('Oeufs au plat à la harissa', '{"en": {"name": "Fried eggs with harissa", "steps": "Heat the olive oil in a pan.\nCrack the eggs and cook over low heat.\nAdd a spoonful of harissa next to the eggs and serve."}, "ar": {"name": "بيض مقلي بالهريسة", "steps": "سخّن زيت الزيتون في مقلاة.\nاكسر البيض واطهه على نار هادئة.\nضع ملعقة هريسة بجانب البيض وقدّمه."}, "aeb": {"name": "بيض مقلي بالهريسة", "steps": "سخّن زيت الزيتون في مقلة.\nكسّر البيض وطيّبو على نار خفيفة.\nحط معلقة هريسة جنب البيض وقدّمو."}}'),
  ('Tartine thon et fromage', '{"en": {"name": "Tuna and cheese toast", "steps": "Drain the tuna and flake it.\nSpread the cheese on the bread and add the tuna.\nPut it in the oven for a few minutes if you like melted cheese."}, "ar": {"name": "خبز بالتونة والجبن", "steps": "صفِّ التونة وفتّتها.\nادهن الخبز بالجبن وأضف التونة.\nضعه في الفرن بضع دقائق إن أردت جبنا ذائبا."}, "aeb": {"name": "خبز بالتن والجبن", "steps": "صفّي التن وفتّتو.\nحط الجبن على الخبز وزيد التن.\nدخّلو للفور شوية دقايق كان تحب الجبن ذايب."}}'),
  ('Fricassé tunisien', '{"en": {"name": "Tunisian fricassé", "steps": "Knead a soft dough (flour, water, yeast) or use fricassé bread, then deep-fry small rolls in hot oil.\nBoil the potatoes and eggs, then cut into pieces.\nOpen the rolls and fill with tuna, potato, egg, olives and harissa."}, "ar": {"name": "فريكاسي تونسي", "steps": "اعجن عجينة طرية (دقيق وماء وخميرة) أو استخدم خبز الفريكاسي، ثم اقلِ أرغفة صغيرة في زيت ساخن.\nاسلق البطاطا والبيض ثم قطّعهما.\nافتح الأرغفة واحشها بالتونة والبطاطا والبيض والزيتون والهريسة."}, "aeb": {"name": "فريكاسي", "steps": "اعجن عجينة طرية (فرينة وماء وخميرة) ولا خذ خبز الفريكاسي، وبعد اقلي كور صغار في زيت سخون.\nاسلق البطاطا والبيض وقطّعهم.\nحل الخبزات واحشيهم بالتن والبطاطا والبيض والزيتون والهريسة."}}'),
  ('Brik à l''oeuf et au thon', '{"en": {"name": "Egg and tuna brik", "steps": "Mix the drained tuna with chopped parsley.\nPlace the filling on a brik sheet and crack an egg in the center.\nFold into a triangle and fry a few minutes on each side."}, "ar": {"name": "بريك بالبيض والتونة", "steps": "اخلط التونة المصفاة مع البقدونس المفروم.\nضع الحشوة على ورقة البريك واكسر بيضة في الوسط.\nاطوها على شكل مثلث واقلها بضع دقائق من كل جانب."}, "aeb": {"name": "بريك بالبيض والتن", "steps": "اخلط التن مصفّي بالمعدنوس مفروم.\nحط الحشو على الملسوقة وكسّر بيضة في النص.\nاطويها مثلث واقليها شوية دقايق من كل جهة."}}'),
  ('Riz au poulet', '{"en": {"name": "Chicken rice", "steps": "Fry the chicken with the onion and grated carrot.\nAdd the washed rice and twice its volume of water, season with salt and spices.\nCover and cook over low heat until the water is absorbed."}, "ar": {"name": "أرز بالدجاج", "steps": "قلّ الدجاج مع البصل والجزر المبشور.\nأضف الأرز المغسول وضعف حجمه من الماء، وتبّل بالملح والتوابل.\nغطّه واطهه على نار هادئة حتى يمتص الماء."}, "aeb": {"name": "أرز بالدجاج", "steps": "قلّي الدجاج مع البصل والجزر مبشور.\nزيد الأرز مغسول وضعف كميتو ماء، وزيد الملح والبهارات.\nغطّي وطيّب على نار خفيفة حتى يشرب الماء."}}'),
  ('Gratin de pommes de terre', '{"en": {"name": "Potato gratin", "steps": "Peel the potatoes and slice them thinly.\nArrange them in a dish, pour over the salted and peppered milk, and top with cheese.\nBake at 180°C (350°F) for 35 to 40 minutes."}, "ar": {"name": "غراتان البطاطا", "steps": "قشّر البطاطا وقطّعها شرائح رقيقة.\nرتّبها في طبق وصبّ فوقها الحليب المملح والمتبّل بالفلفل، وغطّها بالجبن.\nاخبزها في الفرن على 180 درجة لمدة 35 إلى 40 دقيقة."}, "aeb": {"name": "غراتان بطاطا", "steps": "قشّر البطاطا وقطّعها شرايح رقاق.\nرتّبها في طبسي وصبّ عليها الحليب بالملح والفلفل وغطّي بالجبن.\nدخّلها للفور على 180 درجة 35 لـ40 دقيقة."}}'),
  ('Salade tunisienne', '{"en": {"name": "Tunisian salad", "steps": "Dice the tomato, cucumber and onion, and slice the chili pepper.\nSeason with olive oil, lemon juice and salt.\nServe cold."}, "ar": {"name": "سلطة تونسية", "steps": "قطّع الطماطم والخيار والبصل مكعبات صغيرة، والفلفل الحار شرائح.\nتبّل بزيت الزيتون وعصير الليمون والملح.\nقدّمها باردة."}, "aeb": {"name": "سلطة تونسية", "steps": "قطّع الطماطم والخيار والبصل صغار، والفلفل الحار دوائر.\nزيد زيت الزيتون وعصير الليمون والملح.\nقدّمها باردة."}}'),
  ('Salade de thon', '{"en": {"name": "Tuna salad", "steps": "Cut the tomato and hard-boiled egg into pieces.\nAdd the drained tuna and the olives.\nSeason with oil, lemon and salt."}, "ar": {"name": "سلطة التونة", "steps": "قطّع الطماطم والبيضة المسلوقة قطعا.\nأضف التونة المصفاة والزيتون.\nتبّل بالزيت والليمون والملح."}, "aeb": {"name": "سلطة التن", "steps": "قطّع الطماطم والبيضة مسلوقة.\nزيد التن مصفّي والزيتون.\nزيد الزيت والليمون والملح."}}'),
  ('Spaghetti au thon et à la tomate', '{"en": {"name": "Spaghetti with tuna and tomato", "steps": "Cook the pasta in salted water.\nFry the garlic, add the tomato and cook for 10 minutes, then the drained tuna.\nMix with the pasta."}, "ar": {"name": "سباغيتي بالتونة والطماطم", "steps": "اسلق المعكرونة في ماء مملح.\nقلّ الثوم، ثم أضف الطماطم واطهه 10 دقائق، ثم التونة المصفاة.\nاخلط الصلصة مع المعكرونة."}, "aeb": {"name": "سباغيتي بالتن والطماطم", "steps": "اسلق السباغيتي في ماء بالملح.\nقلّي الثوم، زيد الطماطم وطيّب 10 دقايق، وبعد زيد التن مصفّي.\nاخلط الصلصة بالسباغيتي."}}'),
  ('Kefta de boeuf', '{"en": {"name": "Beef kefta", "steps": "Mix the minced meat with chopped onion, garlic and parsley, salt and spices.\nShape into elongated meatballs.\nCook in a pan or on the grill for 10 to 12 minutes, turning them."}, "ar": {"name": "كفتة اللحم البقري", "steps": "اخلط اللحم المفروم مع البصل والثوم والبقدونس المفروم والملح والتوابل.\nشكّله على هيئة أصابع طويلة.\nاطهه في مقلاة أو على الشواية من 10 إلى 12 دقيقة مع تقليبه."}, "aeb": {"name": "كفتة", "steps": "اخلط اللحم المفروم بالبصل والثوم والمعدنوس مفروم والملح والبهارات.\nاعمل منو كور مطوّلة.\nطيّبهم في مقلة ولا على الشواية 10 لـ12 دقيقة وقلّبهم."}}'),
  ('Tajine tunisien au poulet', '{"en": {"name": "Tunisian chicken tajine", "steps": "Cook the shredded chicken with a little onion.\nMix with the beaten eggs, grated cheese, parsley and salt.\nPour into an oiled dish and bake at 180°C (350°F) for 30 minutes."}, "ar": {"name": "طاجين تونسي بالدجاج", "steps": "اطهِ الدجاج المفتّت مع قليل من البصل.\nاخلطه مع البيض المخفوق والجبن المبشور والبقدونس والملح.\nاسكبه في طبق مدهون بالزيت واخبزه في الفرن على 180 درجة لمدة 30 دقيقة."}, "aeb": {"name": "طاجين تونسي بالدجاج", "steps": "طيّب الدجاج مفتّت مع شوية بصل.\nاخلطو بالبيض مخفوق والجبن مبشور والمعدنوس والملح.\nصبّو في طبسي مزيّت ودخّلو للفور على 180 درجة 30 دقيقة."}}'),
  ('Marqa de poulet aux pois chiches', '{"en": {"name": "Chicken and chickpea stew", "steps": "Fry the onion and garlic, add the chicken and brown it.\nAdd the tomato, chickpeas, spices and water.\nSimmer for 35 to 40 minutes over low heat."}, "ar": {"name": "مرقة الدجاج بالحمص", "steps": "قلّ البصل والثوم، ثم أضف الدجاج وحمّره.\nأضف الطماطم والحمص والتوابل والماء.\nاتركه يغلي على نار هادئة من 35 إلى 40 دقيقة."}, "aeb": {"name": "مرقة دجاج بالحمص", "steps": "قلّي البصل والثوم، زيد الدجاج وحمّرو.\nزيد الطماطم والحمص والبهارات والماء.\nخلّيها تطيب على نار خفيفة 35 لـ40 دقيقة."}}'),
  ('Lentilles au riz', '{"en": {"name": "Lentils with rice", "steps": "Boil the lentils in water for 15 minutes.\nAdd the rice and a little water, cook until tender.\nBrown the sliced onion in oil and place it on top."}, "ar": {"name": "عدس بالأرز", "steps": "اسلق العدس في الماء 15 دقيقة.\nأضف الأرز وقليلا من الماء، واطهه حتى ينضج.\nحمّر البصل المقطع في الزيت وضعه فوقه."}, "aeb": {"name": "عدس بالأرز", "steps": "اسلق العدس في الماء 15 دقيقة.\nزيد الأرز وشوية ماء وطيّب حتى يستوي.\nحمّر البصل مقطّع في الزيت وحطو من فوق."}}'),
  ('Poivrons farcis', '{"en": {"name": "Stuffed peppers", "steps": "Mix the minced meat, raw rice, chopped onion, tomato and spices.\nCut the tops off the peppers, empty them and fill them.\nCook them in tomato sauce over low heat, or in the oven, for 45 minutes."}, "ar": {"name": "فلفل محشي", "steps": "اخلط اللحم المفروم والأرز النيء والبصل المفروم والطماطم والتوابل.\nاقطع أعلى حبات الفلفل وفرّغها واحشها.\nاطهها في صلصة الطماطم على نار هادئة أو في الفرن لمدة 45 دقيقة."}, "aeb": {"name": "فلفل محشي", "steps": "اخلط اللحم المفروم والأرز ني والبصل مفروم والطماطم والبهارات.\nاقطع فوق الفلفل وفرّغو واحشيه.\nطيّبو في صلصة الطماطم على نار خفيفة ولا في الفور 45 دقيقة."}}'),
  ('Aubergines frites à la tomate', '{"en": {"name": "Fried eggplant with tomato", "steps": "Slice the eggplants, salt them and let them drain.\nFry them in oil, then drain on paper.\nMake a sauce with garlic, tomato and olive oil, and pour it over the eggplants."}, "ar": {"name": "باذنجان مقلي بالطماطم", "steps": "قطّع الباذنجان شرائح وملّحه واتركه ليفقد مائه.\nاقلِه في الزيت ثم صفّه.\nحضّر صلصة بالثوم والطماطم وزيت الزيتون واسكبها فوق الباذنجان."}, "aeb": {"name": "باذنجان مقلي بالطماطم", "steps": "قطّع الباذنجان شرايح وزيدو الملح وخلّيه يسيّب الماء.\nاقليه في الزيت وصفّيه.\nاعمل صلصة بالثوم والطماطم وزيت الزيتون وصبّها على الباذنجان."}}'),
  ('Chorba à l''agneau', '{"en": {"name": "Lamb chorba", "steps": "Fry the onion and lamb pieces, add the tomato and spices.\nAdd the chickpeas and cover with water, cook 45 minutes.\nServe with dried mint."}, "ar": {"name": "شوربة لحم الضأن", "steps": "قلّ البصل وقطع لحم الضأن، ثم أضف الطماطم والتوابل.\nأضف الحمص وغطّه بالماء، واطهه 45 دقيقة.\nقدّمها مع النعناع المجفف."}, "aeb": {"name": "شربة علوش", "steps": "قلّي البصل والعلوش مقطّع، زيد الطماطم والبهارات.\nزيد الحمص وغطّي بالماء وطيّب 45 دقيقة.\nقدّمها بالنعناع ناشف."}}'),
  ('Poisson grillé au citron', '{"en": {"name": "Grilled fish with lemon", "steps": "Marinate the fish with crushed garlic, olive oil, salt and lemon juice for 15 minutes.\nGrill 5 to 7 minutes on each side depending on size.\nServe with lemon wedges."}, "ar": {"name": "سمك مشوي بالليمون", "steps": "انقع السمك في الثوم المهروس وزيت الزيتون والملح وعصير الليمون لمدة 15 دقيقة.\nاشوه من 5 إلى 7 دقائق من كل جانب حسب الحجم.\nقدّمه مع شرائح الليمون."}, "aeb": {"name": "حوت مشوي بالليمون", "steps": "خلّي الحوت في الثوم مدقوق وزيت الزيتون والملح وعصير الليمون 15 دقيقة.\nاشويه 5 لـ7 دقايق من كل جهة على حسب الحجم.\nقدّمو بشرايح ليمون."}}'),
  ('Soupe de légumes', '{"en": {"name": "Vegetable soup", "steps": "Cut the carrot, potato, zucchini and onion into pieces.\nSauté them for a few minutes, cover with water and cook for 25 minutes.\nBlend or leave chunky, then season."}, "ar": {"name": "شوربة الخضار", "steps": "قطّع الجزر والبطاطا والكوسا والبصل قطعا.\nقلّها بضع دقائق ثم غطّها بالماء واطهها 25 دقيقة.\nاهرسها بالخلاط أو اتركها قطعا، ثم تبّلها."}, "aeb": {"name": "شربة خضرة", "steps": "قطّع الجزر والبطاطا والقرعة والبصل.\nقلّيهم شوية دقايق وغطّي بالماء وطيّب 25 دقيقة.\nاطحنهم بالخلاط ولا خلّيهم قطع، وزيد الملح."}}'),
  ('Omelette aux épinards', '{"en": {"name": "Spinach omelette", "steps": "Fry the garlic and the washed spinach until wilted.\nPour in the beaten eggs and season.\nCook over low heat on both sides."}, "ar": {"name": "عجة بالسبانخ", "steps": "قلّ الثوم والسبانخ المغسولة حتى تذبل.\nاسكب البيض المخفوق وتبّل.\nاطهها على نار هادئة من الجانبين."}, "aeb": {"name": "عجّة بالسبانخ", "steps": "قلّي الثوم والسبانخ مغسولة حتى تنقص.\nصبّ البيض مخفوق وزيد الملح.\nطيّبها على نار خفيفة من الجهتين."}}'),
  ('Doubara aux fèves', '{"en": {"name": "Doubara (fava bean stew)", "steps": "Cook the fava beans in water until very tender.\nMash them lightly with garlic, harissa and olive oil.\nServe hot with bread."}, "ar": {"name": "دوبارة الفول", "steps": "اسلق الفول في الماء حتى يصبح طريا جدا.\nاهرسه قليلا مع الثوم والهريسة وزيت الزيتون.\nقدّمه ساخنا مع الخبز."}, "aeb": {"name": "دوبارة بالفول", "steps": "اسلق الفول في الماء حتى يولي طري برشا.\nاهرسو شوية بالثوم والهريسة وزيت الزيتون.\nقدّمو سخون بالخبز."}}'),
  ('Pizza maison', '{"en": {"name": "Homemade pizza", "steps": "Knead the flour with water, yeast, salt and a little oil, and let rise for 1 hour.\nRoll out the dough and top with tomato sauce, cheese and olives.\nBake at 220°C (430°F) for 15 minutes."}, "ar": {"name": "بيتزا منزلية", "steps": "اعجن الدقيق مع الماء والخميرة والملح وقليل من الزيت، واتركه يختمر ساعة.\nافرد العجينة وغطّها بصلصة الطماطم والجبن والزيتون.\nاخبزها في الفرن على 220 درجة لمدة 15 دقيقة."}, "aeb": {"name": "بيتزا دار", "steps": "اعجن الفرينة بالماء والخميرة والملح وشوية زيت وخلّيها تعلى ساعة.\nافرد العجينة وحط عليها صلصة الطماطم والجبن والزيتون.\nدخّلها للفور على 220 درجة 15 دقيقة."}}'),
  ('Riz au thon', '{"en": {"name": "Tuna rice", "steps": "Fry the onion and tomato.\nAdd the washed rice and water, salt and cook covered.\nStir in the drained tuna at the end of cooking."}, "ar": {"name": "أرز بالتونة", "steps": "قلّ البصل والطماطم.\nأضف الأرز المغسول والماء والملح واطهه مغطى.\nأضف التونة المصفاة في نهاية الطهي."}, "aeb": {"name": "أرز بالتن", "steps": "قلّي البصل والطماطم.\nزيد الأرز مغسول والماء والملح وطيّب مغطّي.\nزيد التن مصفّي في الآخر."}}'),
  ('Pommes de terre sautées aux oeufs', '{"en": {"name": "Sautéed potatoes with eggs", "steps": "Dice the potatoes and brown them with the onion.\nAdd the beaten eggs and stir gently.\nCook until the eggs are set."}, "ar": {"name": "بطاطا مقلية بالبيض", "steps": "قطّع البطاطا مكعبات وحمّرها مع البصل.\nأضف البيض المخفوق وحرّك برفق.\nاطهه حتى يتماسك البيض."}, "aeb": {"name": "بطاطا بالبيض", "steps": "قطّع البطاطا مكعبات وحمّرها مع البصل.\nزيد البيض مخفوق وحرّك بشوية.\nطيّب حتى يتجمّد البيض."}}'),
  ('Gratin de courgettes', '{"en": {"name": "Zucchini gratin", "steps": "Slice the zucchini and lightly sauté them.\nMix the eggs, milk and half the cheese, and add salt.\nPour over the zucchini, top with the remaining cheese and bake at 180°C (350°F) for 30 minutes."}, "ar": {"name": "غراتان الكوسا", "steps": "قطّع الكوسا شرائح وقلّها قليلا.\nاخلط البيض والحليب ونصف الجبن وأضف الملح.\nاسكب الخليط فوق الكوسا وغطّه ببقية الجبن واخبزه على 180 درجة لمدة 30 دقيقة."}, "aeb": {"name": "غراتان قرعة", "steps": "قطّع القرعة شرايح وقلّيها شوية.\nاخلط البيض والحليب ونص الجبن وزيد الملح.\nصبّو على القرعة وغطّي بالباقي من الجبن ودخّلو للفور على 180 درجة 30 دقيقة."}}')
) as v(name, t)
where r.name = v.name;

